export default async function stripeCreateCheckoutSession(
  { sessionToken, sessionSecret, stripeSecretKey, tierId, currency, successUrl, cancelUrl, trialDays },
  { logging, http }
) {
  if (!sessionToken || typeof sessionToken !== 'string' || sessionToken.trim() === '') {
    http?.status(401);
    return { error: 'Unauthorized' };
  }
  if (!sessionSecret) {
    logging.log('Missing SESSION_SECRET configuration');
    http?.status(500);
    return { error: 'Server configuration error' };
  }
  let claims;
  try {
    claims = jwt.verify(sessionToken.trim(), sessionSecret, { algorithms: ['HS256'] });
  } catch (err) {
    logging.log('Session JWT verification failed:', err.name, err.message);
    http?.status(401);
    return { error: 'Unauthorized' };
  }
  const email = claims?.email;
  if (!email || typeof email !== 'string' || !email.includes('@')) {
    logging.log('Session JWT missing valid email claim');
    http?.status(401);
    return { error: 'Unauthorized' };
  }
  logging.log('Session verified for:', email);
  if (!stripeSecretKey || !successUrl || !cancelUrl || !tierId) {
    logging.log('Missing required Stripe configuration');
    http?.status(500);
    return { error: 'Server configuration error' };
  }
  const resolvedCurrency = (currency || 'AUD').toUpperCase();
  const tierPrices = CURRENCY_PRICE_MAP[tierId];
  if (!tierPrices) {
    logging.log('Unknown tier:', tierId);
    http?.status(400);
    return { error: 'Invalid tier' };
  }
  const priceId = tierPrices[resolvedCurrency] || tierPrices['AUD'];
  logging.log('Using price', priceId, 'for currency', resolvedCurrency);
  const stripe = new Stripe(stripeSecretKey, { apiVersion: '2023-10-16' });
  let customerId;
  try {
    const existing = await stripe.customers.search({ query: `email:'${email}'`, limit: 1 });
    if (existing.data.length > 0) {
      customerId = existing.data[0].id;
      logging.log('Found existing Stripe customer:', customerId);
    } else {
      const created = await stripe.customers.create({ email });
      customerId = created.id;
      logging.log('Created new Stripe customer:', customerId);
    }
  } catch (err) {
    logging.log('Stripe customer lookup/create failed:', err.message);
    http?.status(502);
    return { error: 'Failed to resolve customer' };
  }
  const checkoutParams = {
    customer: customerId,
    mode: 'subscription',
    line_items: [{ price: priceId, quantity: 1 }],
    success_url: successUrl,
    cancel_url: cancelUrl,
    automatic_tax: { enabled: true },
    tax_id_collection: { enabled: true }
  };
  if (typeof trialDays === 'number' && trialDays > 0) {
    checkoutParams.subscription_data = { trial_period_days: Math.floor(trialDays) };
    logging.log('Trial period applied:', trialDays, 'days');
  }
  let session;
  try {
    session = await stripe.checkout.sessions.create(checkoutParams);
    logging.log('Checkout session created:', session.id);
  } catch (err) {
    logging.log('Stripe checkout session creation failed:', err.message);
    http?.status(502);
    return { error: 'Failed to create checkout session' };
  }
  return { url: session.url };
}

